public class Main {

  // By solving this can be easily understood

    static Node lca(Node root, Node p, Node q) {

        if(root == null)
            return null;

        if(root == p || root == q)
            return root; 

        // left side
        Node left = lca(root.left, p, q);

        // right side
        Node right = lca(root.right, p, q);

        // if both are not null then that that will be lca 
        if(left != null && right != null)
            return root;

        // if one of the not null then it will return that
        return (left != null) ? left : right;
    }

    public static void main(String[] args) {

        Node root = new Node(3);

        root.left = new Node(5);
        root.right = new Node(1);

        root.left.left = new Node(6);
        root.left.right = new Node(2);

        root.right.left = new Node(0);
        root.right.right = new Node(8);

        root.left.right.left = new Node(7);
        root.left.right.right = new Node(4);

        Node ans = lca(root,
                       root.left.right.left,   // 7
                       root.left.right.right); // 4

        System.out.println(ans.data);
    }
}

