class MyClass {
    public static boolean isSafe(char[][] board, int row, int col) {
        // Horizontal
        for (int j = 0; j < board.length; j++) {
            if (board[row][j] == 'Q') {
                return false;
            }
        }
        // Vertical
        for (int i = 0; i < board.length; i++) {
            if (board[i][col] == 'Q') {
                return false;
            }
        }
        // Left Upper Diagonal
        int r = row;
        for (int j = col; j >= 0 && r >= 0; j--, r--) {
            if (board[r][j] == 'Q') {
                return false;
            }
        }
        // Left Lower Diagonal
        r = row;
        for (int j = col; j >= 0 && r < board.length; j--, r++) {
            if (board[r][j] == 'Q') {
                return false;
            }
        }
        // Right Upper Diagonal
        r = row;
        for (int j = col; j < board.length && r >= 0; j++, r--) {
            if (board[r][j] == 'Q') {
                return false;
            }
        }
        // Right Lower Diagonal
        r = row;
        for (int j = col; j < board.length && r < board.length; j++, r++) {
            if (board[r][j] == 'Q') {
                return false;
            }
        }
        return true;
    }

    public static void nQueens(char[][] board, int row) {

        if (row == board.length) {

            for (char[] r : board) {
                System.out.println(new String(r));
            }

            System.out.println();
            return;
        }
        for (int col = 0; col < board.length; col++) {
            if (isSafe(board, row, col)) {
                board[row][col] = 'Q'; // Choose
                nQueens(board, row + 1); // Explore
                board[row][col] = '.'; // Backtrack
            }
        }
    }

    public static void main(String[] args) {
        int n = 4;
        char[][] board = new char[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                board[i][j] = '.';
            }
        }
        nQueens(board, 0);
    }
}

