public class MyClass {
    static void subsets(int[] arr, int idx, ArrayList<Integer> temp) {
        // Base Case
        if (idx == arr.length) {
            System.out.println(temp);
            return;
        }
        // Not Take
        subsets(arr, idx + 1, temp);

        // Take
        temp.add(arr[idx]); // adding 
        subsets(arr, idx + 1, temp); // after adding exploring next

        // Backtrack
        temp.remove(temp.size() - 1); // after explore Backtrack
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3};
        subsets(arr, 0, new ArrayList<>());
    }
}

class MyClass {

    static void subsequence(String str, int idx, String ans) {
        if (idx == str.length()) {
            System.out.println(ans);
            return;
        }
        // Take current character // subsequence we first take and also pass the ans as parameter
        subsequence(str, idx + 1, ans + str.charAt(idx));

        // Don't take current character
        subsequence(str, idx + 1, ans);
    }

    public static void main(String[] args) {
        String str = "abc";
        subsequence(str, 0, "");
    }
}

