import java.util.Scanner;

public class Main {

    static int findPeakElement(int[] arr) {
        int low = 0;
        int high = arr.length - 1;

        while (low < high) {
            int mid = low + (high - low) / 2;

            // If the element to the right is greater, 
            // then a peak must exist on the right half.
            if (arr[mid] < arr[mid + 1]) {
                low = mid + 1;
            } 
            // Otherwise, a peak lies on the left half (including mid).
            else {
                high = mid;
            }
        }

        // 'low' and 'high' will converge to the peak element's index
        return low;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read the size of the array
        int n = scanner.nextInt();
        int arr[] = new int[n];

        // Read the array elements
        for (int i = 0; i < n; i++) {
            arr[i] = scanner.nextInt();
        }

        // Find and print the peak element's index
        int peakIndex = findPeakElement(arr);
        System.out.println(peakIndex);

        scanner.close();
    }
}

